const item=$input.first().json;
const records=Array.isArray(item.candidate_records)?item.candidate_records:[];
function splitOwner(name){
  const parts=String(name||'').trim().split(/\\s+/).filter(Boolean);
  return {first_name:parts.shift()||'Unknown',last_name:parts.join(' ')||'Owner'};
}
return records.map((candidate,index)=>{
  const owner=splitOwner(candidate.owner_name);
  const externalId=String(candidate.external_id||candidate.parcel_id||candidate.normalized_identity_key||candidate.candidate_key||`${item.request_id||'wf032'}:${index}`);
  return {json:{
    qualification_context:{
      request_id:item.request_id||null,
      state:item.state||null,
      county:item.county||null,
      criteria:item.criteria||[],
      qualification:candidate.qualification||{}
    },
    candidate,
    crm_payload:{
      first_name:owner.first_name,
      last_name:owner.last_name,
      phone:candidate.phone||candidate.owner_phone||null,
      email:candidate.email||candidate.owner_email||null,
      source:'distressed_lead_qualification',
      notes:JSON.stringify({
        qualification:candidate.qualification||{},
        matched_criteria:candidate.matched_criteria||[],
        evidence_count:candidate.evidence_count||0,
        property_address:candidate.property_address||null,
        county:item.county||candidate.county||null,
        state:item.state||candidate.state||null
      }),
      property_address:candidate.property_address||null,
      property_city:candidate.property_city||candidate.city||null,
      property_state:candidate.property_state||candidate.state||item.state||null,
      property_zip:candidate.property_zip||candidate.zip||null,
      property_type:candidate.property_type||null,
      external_id:externalId,
      external_source:'wf032_distressed_lead_qualification'
    }
  }};
});

const results=$input.all().map(x=>x.json);
const synced=results.filter(r=>r && (r.success===true || r.lead_id || r.data?.lead_id));
return [{json:{
  success:true,
  qualification_handoff:true,
  crm_sync_configured:Boolean($env.INSULA_CRM_BASE_URL && $env.INSULA_CRM_API_KEY),
  crm_synced_count:synced.length,
  crm_results:results.map(r=>({success:r.success??Boolean(r.lead_id),lead_id:r.lead_id??r.data?.lead_id??null,duplicate:r.duplicate??false,external_id:r.external_id??null,external_source:r.external_source??null})),
  message:synced.length?'Qualified candidates were handed off to InsulaCRM using external identity and idempotency protection.':'No CRM lead records were synced; verify InsulaCRM environment configuration and candidate qualification output.'
}}];
